import sys

class Notification:
    def notificationBySms(self):
        pass

    def notificationByEmail(self):
        pass

    def notificationByCourier(self):
        pass

class Icici(Notification):
    def notificationBySms(self):
        return "ICICI - Notification By SMS"

    def notificationByEmail(self):
        return "ICICI - Notification By Email"

    def notificationByCourier(self):
        return "ICICI - Notification By Courier"

class Hdfc(Notification):
    def notificationBySms(self):
        return "HDFC - Notification By SMS"

    def notificationByEmail(self):
        return "HDFC - Notification By Email"

    def notificationByCourier(self):
        return "HDFC - Notification By Courier"

class BankFactory:
    def getIcici(self):
        return Icici()

    def getHdfc(self):
        return Hdfc()

def main():
    try:
        line = sys.stdin.readline().strip()
        if not line:
            print("Invalid input")
            return

        parts = line.split()
        if len(parts) != 2:
            print("Invalid input")
            return

        bank = int(parts[0])
        notification_type = int(parts[1])

        factory = BankFactory()

        if bank == 1:
            obj = factory.getIcici()
        elif bank == 2:
            obj = factory.getHdfc()
        else:
            print("Invalid input")
            return

        if notification_type < 1 or notification_type > 3:
            print("Invalid input")
            return

        if notification_type == 1:
            print(obj.notificationBySms())
        elif notification_type == 2:
            print(obj.notificationByEmail())
        elif notification_type == 3:
            print(obj.notificationByCourier())

    except:
        print("Invalid input")

if __name__ == "__main__":
    main()
